word_counter.code:
def execute(params):
    text = params.get('text', '')
    words = text.split()
    return {
        'word_count': len(words),
        'char_count': len(text),
        'avg_word_length': sum(len(w) for w in words) / len(words) if words else 0
    }

fibonacci.code:
def execute(params):
    n = params.get('n', 10)
    fib = [0, 1]
    for i in range(2, n):
        fib.append(fib[-1] + fib[-2])
    return {'sequence': fib[:n], 'nth_value': fib[n-1] if n > 0 else 0}

url_validator.code:
def execute(params):
    from urllib.parse import urlparse
    url = params.get("url", "")
    try:
        parsed = urlparse(url)
        valid = all([parsed.scheme, parsed.netloc])
        return {
            "valid": valid,
            "scheme": parsed.scheme or None,
            "domain": parsed.netloc or None,
            "path": parsed.path or None,
            "query": parsed.query or None
        }
    except:
        return {"valid": False, "error": "Could not parse URL"}
